"""Abstract base class and types for art generator adapters."""
from abc import ABC, abstractmethod
from pathlib import Path
from typing import Any
from pydantic import BaseModel, ConfigDict, Field

from poster_agent.spec.models import PosterSpec


class GeneratedArt(BaseModel):
    """Artifact generated by an image generator adapter."""
    model_config = ConfigDict(extra="forbid")
    image_path: Path
    seed: int
    payload: dict[str, Any] = Field(default_factory=dict)
    prompt_used: str = ""


class GeneratorAdapter(ABC):
    """Base interface for all poster art generators."""

    @abstractmethod
    def generate(
        self,
        spec: PosterSpec,
        count: int = 1,
        base_seed: int | None = None,
        output_dir: Path | str | None = None,
        strategy: str | None = None,
    ) -> list[GeneratedArt]:
        """Generate art image(s) from a PosterSpec.
        Returns a list of GeneratedArt items (one per candidate).
        """
        pass

